import cmath, json, math
N_SLOTS = 8

def phase(k):
    return cmath.exp(1j * 2 * math.pi * k / N_SLOTS)

pairs = [(0, 1.0), (3, -0.5), (5, 2.0)]
state = 0j
for k, v in pairs:
    state += v * phase(k)

def recall(q):
    return (state * phase(q).conjugate()).real

expected = {"recall_key_0": recall(0), "recall_key_3": recall(3), "recall_key_6": recall(6), "state_norm": abs(state)}
print(json.dumps({k: round(v, 9) for k, v in expected.items()}, sort_keys=True))
